package com.example.user.security;
import com.example.common.exception.CustomBusinessException; import com.example.user.config.MailCenterProperties; import org.springframework.stereotype.Component; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.Instant;
@Component public class InternalMailRequestVerifier { private final MailCenterProperties props; public InternalMailRequestVerifier(MailCenterProperties props){this.props=props;} public String sign(long timestamp,String eventId,byte[] body){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret().getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return java.util.HexFormat.of().formatHex(mac.doFinal(payload(timestamp,eventId,body).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new CustomBusinessException("内部邮件签名不可用",503);}} public void verify(long timestamp,String eventId,String signature,byte[] body){long skew=props.internal()==null?300:props.internal().maxClockSkewSeconds();if(Math.abs(Instant.now().getEpochSecond()-timestamp)>skew)throw new CustomBusinessException("内部邮件请求已过期",403);byte[] received;try{received=java.util.HexFormat.of().parseHex(signature);}catch(Exception e){throw new CustomBusinessException("内部邮件签名无效",403);}if(!MessageDigest.isEqual(java.util.HexFormat.of().parseHex(sign(timestamp,eventId,body)),received))throw new CustomBusinessException("内部邮件签名无效",403);} private String secret(){String s=props.internal()==null?null:props.internal().hmacSecret();if(s==null||s.trim().getBytes(StandardCharsets.UTF_8).length<32)throw new CustomBusinessException("内部邮件签名未配置",503);return s.trim();} private String payload(long timestamp,String id,byte[] body){try{return timestamp+"\n"+id+"\n"+java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(body));}catch(Exception e){throw new IllegalStateException(e);}} }
